function hide(){$('tooltip').hidden=true;}
function show(e){const p=e.target.closest('circle[data-tip]');if(!p)return;const tip=$('tooltip');tip.textContent=p.dataset.tip;tip.hidden=false;const r=p.getBoundingClientRect(),x=e.clientX||r.x,y=e.clientY||r.y;tip.style.left=Math.max(8,Math.min(x+12,innerWidth-tip.offsetWidth-8))+'px';tip.style.top=Math.max(8,Math.min(y+12,innerHeight-tip.offsetHeight-8))+'px';}
