const value=(r,k)=>k==='actual'?r.actual_price:r[cols[k]],values=subset.flatMap(r=>keys.map(k=>value(r,k))),min=Math.min(0,...values),max=Math.max(0,...values),pad=(max-min||1)*.08,lo=min-pad,hi=max+pad,w=1100,h=420,l=75,right=25,top=20,bottom=58,X=i=>l+i*(w-l-right)/(subset.length-1||1),Y=v=>top+(hi-v)*(h-top-bottom)/(hi-lo);
let out='';for(let j=0;j<=4;j++){const v=lo+(hi-lo)*j/4;out+=`<line x1="${l}" y1="${Y(v)}" x2="${w-right}" y2="${Y(v)}" stroke="#293b51"/><text x="${l-10}" y="${Y(v)+4}" text-anchor="end" fill="#9cb0ca" font-size="12">${f(v)}</text>`;}
const step=Math.max(1,Math.ceil(subset.length/6));subset.forEach((r,i)=>{if(i%step===0)out+=`<text x="${X(i)}" y="${h-25}" text-anchor="middle" fill="#9cb0ca" font-size="11">${r.hour_start.slice(5,16)}</text>`;});
