render();
(async()=>{try{const response=await fetch('../data/processed/vic_nonlinear_validation.csv');if(!response.ok)throw Error('HTTP '+response.status);const lines=(await response.text()).trim().split(/\r?\n/),heads=lines.shift().split(',');for(const key of ['hour_start','actual_price',...Object.values(cols)])if(!heads.includes(key))throw Error('Unexpected columns');data=lines.map(line=>{const values=line.split(',');return Object.fromEntries(heads.map((h,i)=>[h,h==='hour_start'?values[i]:Number(values[i])]));});if(data.length!==720||data.some((r,i)=>r.hour_start!==new Date(Date.UTC(2026,8,1,i)).toISOString().slice(0,19).replace('T',' ')||['actual_price',...Object.values(cols)].some(k=>!Number.isFinite(r[k]))))throw Error('Invalid validation coverage');}catch(e){data=null;error=e.message;}render();})();
